class Solution:
    def maximumNumberOfOnes(self, width: int, height: int, sideLength: int, maxOnes: int) -> int:
        s = sideLength
        freq = []
        for r in range(s):
            for c in range(s):
                rows = (height - r + s - 1) // s
                cols = (width - c + s - 1) // s
                freq.append(rows * cols)
        freq.sort(reverse=True)
        return sum(freq[:maxOnes])

