import heapq
class Solution:
    def maximumNumberOfOnes(self, width: int, height: int, sideLength: int, maxOnes: int) -> int:
        s = sideLength
        heap = []
        for r in range(min(s, height)):
            rc = (height - r + s - 1) // s
            for c in range(min(s, width)):
                cc = (width - c + s - 1) // s
                heapq.heappush(heap, -(rc * cc))
        return -sum(heapq.heappop(heap) for _ in range(maxOnes))

