class Solution {
public:
    int maximumNumberOfOnes(int width, int height, int sideLength, int maxOnes) {
        int s = sideLength;
        priority_queue<int> pq;
        for (int r = 0; r < min(s, height); r++) {
            long long rc = (height - r + s - 1LL) / s;
            for (int c = 0; c < min(s, width); c++) {
                long long cc = (width - c + s - 1LL) / s;
                pq.push(rc * cc);
            }
        }
        long long ans = 0;
        for (int i = 0; i < maxOnes; i++) { ans += pq.top(); pq.pop(); }
        return (int)ans;
    }
};

