class Solution {
    public int maximumNumberOfOnes(int width, int height, int sideLength, int maxOnes) {
        int s = sideLength;
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        for (int r = 0; r < Math.min(s, height); r++) {
            int rc = (height - r + s - 1) / s;
            for (int c = 0; c < Math.min(s, width); c++) {
                int cc = (width - c + s - 1) / s;
                pq.offer(rc * cc);
            }
        }
        int ans = 0;
        for (int i = 0; i < maxOnes; i++) ans += pq.poll();
        return ans;
    }
}

